  "specVersion": "1.0.0",
  "name": "example-html-ppt-tech-sharing",
  "title": "Html Ppt Tech Sharing",
  "title_i18n": {
    "zh-CN": "Html Ppt 技术分享",
    "zh-TW": "Html Ppt 技術分享",
    "ja": "Html Ppt Tech Sharing",
    "ko": "Html Ppt Tech Sharing",
    "de": "Html Ppt Tech Sharing",
    "fr": "Html Ppt Tech Sharing",
    "ru": "Html Ppt Tech Sharing",
    "es": "Html Ppt Tech Sharing",
    "pt-BR": "Html Ppt Tech Sharing",
    "it": "Html Ppt Tech Sharing",
    "vi": "Html Ppt Tech Sharing",
    "pl": "Html Ppt Tech Sharing",
    "id": "Html Ppt Tech Sharing",
    "nl": "Html Ppt Tech Sharing",
